<?php
namespace App\Services;
use App\Enums\AppointmentStatus; use App\Enums\PaymentStatus; use App\Exceptions\InvalidAppointmentActionException; use App\Jobs\SendAppointmentCancellation; use App\Models\Appointment; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\DB;
class AppointmentLifecycleService { public function __construct(private SlotService $slots,private SlotCacheService $cache){} public function cancel(Appointment $appointment,?string $reason): Appointment { if(!in_array($appointment->status,[AppointmentStatus::Pending,AppointmentStatus::Confirmed],true)){throw new InvalidAppointmentActionException('Only pending or confirmed appointments can be cancelled.');} if($appointment->status===AppointmentStatus::Confirmed&&now()->addHours(config('booking.cancel_before_hours',6))->gt($appointment->starts_at)){throw new InvalidAppointmentActionException('The cancellation deadline has passed.');} DB::transaction(function() use($appointment,$reason){$appointment->update(['status'=>AppointmentStatus::Cancelled,'cancelled_at'=>now(),'cancellation_reason'=>$reason]);if($appointment->payment){$appointment->payment->update($appointment->payment->status===PaymentStatus::Paid?['status'=>PaymentStatus::Refunded,'refunded_at'=>now()]:['status'=>PaymentStatus::Failed]);} SendAppointmentCancellation::dispatch($appointment->id)->afterCommit();});$this->cache->invalidate($appointment->provider_id);return $appointment->fresh('payment'); }
public function reschedule(Appointment $appointment,string $startsAt): Appointment { if($appointment->status!==AppointmentStatus::Confirmed){throw new InvalidAppointmentActionException('Only confirmed appointments can be rescheduled.');} if(now()->addHours(config('booking.cancel_before_hours',6))->gt($appointment->starts_at)){throw new InvalidAppointmentActionException('The reschedule deadline has passed.');} $provider=$appointment->provider;$service=$appointment->service; return Cache::lock("booking:provider:{$provider->id}",10)->block(5,function() use($appointment,$provider,$service,$startsAt){return DB::transaction(function() use($appointment,$provider,$service,$startsAt){if(DB::getDriverName()==='pgsql'){DB::select('SELECT pg_advisory_xact_lock(?)',[$provider->id]);}$local=CarbonImmutable::parse($startsAt)->setTimezone($provider->timezone);$slots=$this->slots->availableSlots($provider,$service,$local->format('Y-m-d'),$appointment->id,false);$target=collect($slots)->first(fn($s)=>CarbonImmutable::parse($s['starts_at'])->equalTo(CarbonImmutable::parse($startsAt)));if(!$target){throw new InvalidAppointmentActionException('The requested reschedule time is unavailable.');}$start=CarbonImmutable::parse($startsAt)->utc();$appointment->update(['starts_at'=>$start,'ends_at'=>$start->addMinutes($appointment->duration_minutes),'rescheduled_at'=>now(),'reminder_queued_at'=>null]);$this->cache->invalidate($provider->id);return $appointment->fresh('payment');});}); } }
